__global__ void linear_relu(const float* input, const float* weight, const float* bias, float* output, int n) {
  int i = blockIdx.x * blockDim.x + threadIdx.x;
  if (i >= n) {
    return;
  }
  int row = i / 2;
  int outCol = i % 2;
  float sum = bias[outCol];
  for (int k = 0; k < 3; k++) {
    sum += input[row * 3 + k] * weight[outCol * 3 + k];
  }
  if (sum > 0.0f) {
    output[i] = sum;
  } else {
    output[i] = 0.0f;
  }
}
